//! Port of Go's `internal/template` engine: built-in templates, custom
//! `~/.config/symvault/templates/<kind>.tmpl` templates and rendering through
//! the Go `text/template`-compatible interpreter in `gotemplate`.

use crate::gotemplate::{self, Bytes, PlainData};
use std::collections::{BTreeMap, HashMap};
use std::ffi::{OsStr, OsString};
use std::path::PathBuf;

/// Go's `builtinTemplates()` (internal/template/builtins.go), verbatim.
const BUILTINS: &[(&str, &str)] = &[
    (
        "env",
        "# Generated by Symaira Vault\n{{- range $key, $ref := .Refs }}\nexport {{ $key }}={{ index $.Values $key }}\n{{- end }}\n",
    ),
    (
        "docker-compose",
        "version: \"3.8\"\nservices:\n  app:\n    environment:\n{{- range $key, $ref := .Refs }}\n      - {{ $key }}={{ index $.Values $key }}\n{{- end }}\n    secrets:\n{{- range $key, $ref := .Refs }}\n      - {{ $key | lower }}_secret\n{{- end }}\nsecrets:\n{{- range $key, $ref := .Refs }}\n  {{ $key | lower }}_secret:\n    file: ./secrets/{{ $key | lower }}.txt\n{{- end }}\n",
    ),
    (
        "k8s-secret",
        "apiVersion: v1\nkind: Secret\nmetadata:\n  name: {{ .Name }}\ntype: Opaque\ndata:\n{{- range $key, $ref := .Refs }}\n  {{ $key }}: {{ index $.Values $key | b64enc }}\n{{- end }}\n",
    ),
    (
        "github-actions",
        "name: Deploy {{ .Name }}\n\non:\n  push:\n    branches: [main]\n\njobs:\n  deploy:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - name: Configure secrets\n        env:\n{{- range $key, $ref := .Refs }}\n          {{ $key }}: {{ index $.Values $key }}\n{{- end }}\n        run: |\n          echo \"Secrets configured\"\n",
    ),
    (
        "terraform",
        "# Terraform variables for {{ .Name }}\n# Generated by Symaira Vault\n{{- range $key, $ref := .Refs }}\nvariable \"{{ $key | lower }}\" {\n  type      = string\n  sensitive = true\n  default   = {{ index $.Values $key | tojson }}\n}\n{{- end }}\n",
    ),
];

/// The source of a built-in template.
#[must_use]
pub fn builtin_source(kind: &str) -> Option<&'static str> {
    BUILTINS
        .iter()
        .find(|(name, _)| *name == kind)
        .map(|(_, src)| *src)
}

/// Custom templates loaded from a directory (`Engine.LoadCustomTemplates`).
#[derive(Clone, Debug, Default)]
pub struct CustomTemplates {
    sources: HashMap<Bytes, Bytes>,
}

fn os_bytes(s: &OsStr) -> Bytes {
    #[cfg(unix)]
    {
        use std::os::unix::ffi::OsStrExt;
        s.as_bytes().to_vec()
    }
    #[cfg(not(unix))]
    {
        s.to_string_lossy().into_owned().into_bytes()
    }
}

/// `os.ExpandEnv("$HOME/.config/symvault/templates")`: an unset `$HOME`
/// expands to the empty string, which leaves an absolute path.
#[must_use]
pub fn custom_template_dir() -> PathBuf {
    let mut dir: OsString = std::env::var_os("HOME").unwrap_or_default();
    dir.push("/.config/symvault/templates");
    PathBuf::from(dir)
}

impl CustomTemplates {
    /// `LoadCustomTemplates(dir)` with the caller's `_ =` applied: any read
    /// failure discards the whole directory (the engine keeps no customs).
    #[must_use]
    pub fn load(dir: &std::path::Path) -> Self {
        Self::try_load(dir).unwrap_or_default()
    }

    /// Load from `$HOME/.config/symvault/templates`.
    #[must_use]
    pub fn load_default() -> Self {
        Self::load(&custom_template_dir())
    }

    fn try_load(dir: &std::path::Path) -> std::io::Result<Self> {
        let mut sources = HashMap::new();
        for entry in std::fs::read_dir(dir)? {
            let entry = entry?;
            // Go's DirEntry.IsDir does not follow symlinks.
            if entry.file_type()?.is_dir() {
                continue;
            }
            let file_name = os_bytes(&entry.file_name());
            let Some(stem) = file_name.strip_suffix(b".tmpl") else {
                continue;
            };
            let content = std::fs::read(entry.path())?;
            sources.insert(stem.to_vec(), content);
        }
        Ok(CustomTemplates { sources })
    }

    #[must_use]
    pub fn contains(&self, kind: &str) -> bool {
        self.sources.contains_key(kind.as_bytes())
    }
}

/// `Engine.getTemplateSource`: custom templates shadow the built-ins.
///
/// # Errors
///
/// `template not found: <kind>` (Go's `ErrTemplateNotFound` wrapping).
pub fn template_source(kind: &str, custom: &CustomTemplates) -> Result<Bytes, String> {
    if let Some(src) = custom.sources.get(kind.as_bytes()) {
        return Ok(src.clone());
    }
    if let Some(src) = builtin_source(kind) {
        return Ok(src.as_bytes().to_vec());
    }
    Err(format!("template not found: {kind}"))
}

/// The parse + execute half of `Engine.Render`.
///
/// # Errors
///
/// Go's `parse template "<kind>": ...` / `execute template "<kind>": ...`
/// error text (lossily decoded if it contains invalid UTF-8).
pub fn render_source(
    kind: &str,
    src: &[u8],
    name: &str,
    refs: &BTreeMap<String, String>,
    values: &BTreeMap<String, String>,
) -> Result<Bytes, String> {
    let to_map = |m: &BTreeMap<String, String>| {
        m.iter()
            .map(|(k, v)| (k.as_bytes().to_vec(), v.as_bytes().to_vec()))
            .collect()
    };
    let data = PlainData {
        name: name.as_bytes().to_vec(),
        refs: to_map(refs),
        values: to_map(values),
    };
    gotemplate::render(kind.as_bytes(), src, data)
        .map_err(|e| String::from_utf8_lossy(&e).into_owned())
}

/// `Engine.Render(..., dryRun=true)` as the MCP tool calls it: custom
/// templates from `$HOME` first, then the built-ins; every value is `***`.
///
/// # Errors
///
/// The text Go's engine returns (the caller adds `render template: `).
pub fn render_masked(
    kind: &str,
    name: &str,
    refs: &BTreeMap<String, String>,
) -> Result<String, String> {
    let custom = CustomTemplates::load_default();
    let src = template_source(kind, &custom)?;
    let values = refs
        .keys()
        .map(|alias| (alias.clone(), "***".to_owned()))
        .collect();
    let out = render_source(kind, &src, name, refs, &values)?;
    Ok(String::from_utf8_lossy(&out).into_owned())
}

/// Render a built-in template from already-resolved values (no custom
/// lookup); `.Refs` carries the same aliases with empty references.
///
/// # Errors
///
/// `template not found: <kind>` or an interpreter error.
pub fn render_builtin(
    kind: &str,
    name: &str,
    values: &BTreeMap<String, String>,
) -> Result<String, String> {
    let src = builtin_source(kind).ok_or_else(|| format!("template not found: {kind}"))?;
    let refs = values
        .keys()
        .map(|alias| (alias.clone(), String::new()))
        .collect();
    let out = render_source(kind, src.as_bytes(), name, &refs, values)?;
    Ok(String::from_utf8_lossy(&out).into_owned())
}

#[cfg(test)]
mod tests {
    use super::*;
    use base64::{Engine as _, engine::general_purpose::STANDARD};
    use std::fmt::Write as _;

    /// The hand-written renderer the interpreter replaced; kept as an
    /// independent expectation for the built-ins.
    fn hand_written(
        kind: &str,
        name: &str,
        values: &BTreeMap<String, String>,
    ) -> Result<String, String> {
        let mut output = match kind {
            "env" => "# Generated by Symaira Vault".to_owned(),
            "docker-compose" => "version: \"3.8\"\nservices:\n  app:\n    environment:".to_owned(),
            "k8s-secret" => format!(
                "apiVersion: v1\nkind: Secret\nmetadata:\n  name: {name}\ntype: Opaque\ndata:"
            ),
            "github-actions" => format!(
                "name: Deploy {name}\n\non:\n  push:\n    branches: [main]\n\njobs:\n  deploy:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - name: Configure secrets\n        env:"
            ),
            "terraform" => {
                format!("# Terraform variables for {name}\n# Generated by Symaira Vault")
            }
            _ => return Err(format!("template not found: {kind}")),
        };
        for (key, value) in values {
            match kind {
                "env" => {
                    let _ = write!(output, "\nexport {key}={value}");
                }
                "docker-compose" => {
                    let _ = write!(output, "\n      - {key}={value}");
                }
                "k8s-secret" => {
                    let _ = write!(output, "\n  {key}: {}", STANDARD.encode(value));
                }
                "github-actions" => {
                    let _ = write!(output, "\n          {key}: {value}");
                }
                "terraform" => {
                    let encoded = symvault_gojson::to_string(value).unwrap();
                    let _ = write!(
                        output,
                        "\nvariable \"{}\" {{\n  type      = string\n  sensitive = true\n  default   = {encoded}\n}}",
                        symvault_core::go_to_lower(key)
                    );
                }
                _ => unreachable!(),
            }
        }
        if kind == "docker-compose" {
            output.push_str("\n    secrets:");
            for key in values.keys() {
                let _ = write!(
                    output,
                    "\n      - {}_secret",
                    symvault_core::go_to_lower(key)
                );
            }
            output.push_str("\nsecrets:");
            for key in values.keys() {
                let key = symvault_core::go_to_lower(key);
                let _ = write!(output, "\n  {key}_secret:\n    file: ./secrets/{key}.txt");
            }
        } else if kind == "github-actions" {
            output.push_str("\n        run: |\n          echo \"Secrets configured\"");
        }
        output.push('\n');
        Ok(output)
    }

    #[test]
    fn interpreter_matches_the_hand_written_builtins() {
        let sets: Vec<BTreeMap<String, String>> = vec![
            BTreeMap::new(),
            BTreeMap::from([("A".into(), "one".into())]),
            BTreeMap::from([
                ("B".into(), "two <&> \"q\"".into()),
                ("a_b".into(), "héllo\nworld".into()),
                ("İSTANBUL".into(), "***".into()),
            ]),
        ];
        for (kind, _) in BUILTINS {
            for values in &sets {
                assert_eq!(
                    render_builtin(kind, "my app", values).unwrap(),
                    hand_written(kind, "my app", values).unwrap(),
                    "{kind} {values:?}"
                );
            }
        }
        assert_eq!(
            render_builtin("nope", "app", &BTreeMap::new()).unwrap_err(),
            "template not found: nope"
        );
    }

    #[test]
    fn custom_templates_shadow_builtins_and_follow_go_loading_rules() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(dir.path().join("env.tmpl"), "custom {{ .Name }}").unwrap();
        std::fs::write(dir.path().join("extra.tmpl"), "x").unwrap();
        std::fs::write(dir.path().join("notes.txt"), "ignored").unwrap();
        std::fs::create_dir(dir.path().join("folder.tmpl")).unwrap();
        let custom = CustomTemplates::load(dir.path());
        assert!(custom.contains("env") && custom.contains("extra"));
        assert!(!custom.contains("notes") && !custom.contains("folder"));
        assert_eq!(
            template_source("env", &custom).unwrap(),
            b"custom {{ .Name }}"
        );
        assert_eq!(
            template_source("terraform", &custom).unwrap(),
            builtin_source("terraform").unwrap().as_bytes()
        );
        assert_eq!(
            template_source("missing", &custom).unwrap_err(),
            "template not found: missing"
        );
    }

    #[cfg(unix)]
    #[test]
    fn one_unreadable_template_discards_the_whole_directory() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(dir.path().join("good.tmpl"), "ok").unwrap();
        std::os::unix::fs::symlink("/nonexistent/target", dir.path().join("dangling.tmpl"))
            .unwrap();
        let custom = CustomTemplates::load(dir.path());
        assert!(!custom.contains("good"));
        assert!(!CustomTemplates::load(&dir.path().join("absent")).contains("good"));
    }
}
